create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,role text not null check(role in('buyer','provider')),created_at timestamptz default now());
create table public.intents(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references public.profiles(id) on delete cascade,description text not null,budget_max numeric check(budget_max>=0),location text,deadline date,status text not null default 'open' check(status in('open','matched','closed','cancelled')),accepted_offer_id uuid,created_at timestamptz default now());
create table public.offers(id uuid primary key default gen_random_uuid(),intent_id uuid not null references public.intents(id) on delete cascade,provider_id uuid not null references public.profiles(id) on delete cascade,amount numeric not null check(amount>=0),message text,status text not null default 'pending' check(status in('pending','accepted','declined','withdrawn')),created_at timestamptz default now(),unique(intent_id,provider_id));
alter table public.intents add constraint intents_accepted_offer_fkey foreign key(accepted_offer_id) references public.offers(id);
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,kind text not null,body text not null,read_at timestamptz,created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',''),coalesce(new.raw_user_meta_data->>'role','buyer')); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table profiles enable row level security; alter table intents enable row level security; alter table offers enable row level security; alter table notifications enable row level security;
create policy "profiles readable authenticated" on profiles for select to authenticated using(true); create policy "own profile update" on profiles for update to authenticated using(id=auth.uid());
create policy "buyers create own intents" on intents for insert to authenticated with check(buyer_id=auth.uid() and exists(select 1 from profiles p where p.id=auth.uid() and p.role='buyer'));
create policy "buyers read own intents providers read open" on intents for select to authenticated using(buyer_id=auth.uid() or (status='open' and exists(select 1 from profiles p where p.id=auth.uid() and p.role='provider')));
create policy "providers create own offers" on offers for insert to authenticated with check(provider_id=auth.uid() and exists(select 1 from profiles p where p.id=auth.uid() and p.role='provider'));
create policy "offer parties read" on offers for select to authenticated using(provider_id=auth.uid() or exists(select 1 from intents i where i.id=intent_id and i.buyer_id=auth.uid()));
create policy "own notifications" on notifications for select to authenticated using(user_id=auth.uid());
create or replace function public.accept_offer(p_offer_id uuid,p_intent_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from intents where id=p_intent_id and buyer_id=auth.uid() and status='open') then raise exception 'Not allowed'; end if; if not exists(select 1 from offers where id=p_offer_id and intent_id=p_intent_id) then raise exception 'Invalid offer'; end if; update offers set status=case when id=p_offer_id then 'accepted' else 'declined' end where intent_id=p_intent_id; update intents set status='matched',accepted_offer_id=p_offer_id where id=p_intent_id; insert into notifications(user_id,kind,body) select provider_id,'offer_accepted','Your offer was accepted.' from offers where id=p_offer_id; end $$;
